from fractions import Fraction
from math import comb
from functools import lru_cache
import random

def bell(n, k, x):
    # x is a tuple, x[i-1] = x_i; partial Bell polynomial B_{n,k}
    @lru_cache(None)
    def B(n, k):
        if n == 0 and k == 0: return Fraction(1)
        if n == 0 or k == 0: return Fraction(0)
        s = Fraction(0)
        for i in range(1, n - k + 2):
            xi = x[i-1] if i-1 < len(x) else Fraction(0)
            s += comb(n-1, i-1) * xi * B(n-i, k-1)
        return s
    return B(n, k)

# sanity: B_{4,2}(x1,x2,x3) = 4 x1 x3 + 3 x2^2
a, b, c3 = Fraction(2), Fraction(3), Fraction(5)
assert bell(4, 2, (a, b, c3)) == 4*a*c3 + 3*b*b

# Assumed interpretation (the notation is ambiguous): (f->g)^c replaces the
# first c arguments f^(j) by g^(j); (g->f)^(n-c) replaces the first n-c g^(j) by f^(j).
def lhs(n, k, c, F, G):
    m = n - k + 1
    args = tuple(G[j] if j < c else F[j] for j in range(m))
    return bell(n, k, args)

def rhs(n, k, c, F, G):
    m = n - k + 1
    args = tuple(F[j] if j < n - c else G[j] for j in range(m))
    return bell(n, k, args)

random.seed(1)
cex = None
equal_cases = 0
total = 0
for n in range(1, 7):
    for k in range(1, n + 1):
        for c in range(0, n + 1):
            F = [Fraction(random.randint(1, 9)) for _ in range(n)]
            G = [Fraction(random.randint(10, 19)) for _ in range(n)]
            total += 1
            L, R = lhs(n, k, c, F, G), rhs(n, k, c, F, G)
            if L == R:
                equal_cases += 1
            elif cex is None:
                cex = (n, k, c, L, R)

print("cases tested:", total, "equal:", equal_cases)
print("counterexample (n,k,c,LHS,RHS):", cex)
if cex:
    print("Equality fails in general (sampled counterexample, under the stated interpretation).")
    print("CHECK PASS: answer 'No' supported")
else:
